files.nginx.conf:
server {
  listen 80;
  server_name api.internal.local;
  location / {
    proxy_pass http://localhost:8080;
    proxy_set_header Host $host;
  }
}

app.server.js:
const http = require('http');
const server = http.createServer((req, res) => res.end('OK'));
server.listen(8080);

